// Негативный тест: комментарий Анны к её тренировке видят она и её тренер Марина, а Света, подопечная Игоря, — нет;
// Света не может написать под тренировкой Анны, а Анна — от имени Марины.
// Права проверяет база (RLS, supabase/migrations/0007_comments_rls.sql): запросы идут от имени разных людей, как в asUser из lib/db.ts.
// Данные тест создаёт сам в одной транзакции и в конце откатывает (rollback): в базе после него ничего не остаётся.
// Нужна база с миграциями и seed из supabase/, адрес — DATABASE_URL из окружения, как у test/rls.test.ts.
import type { PoolClient } from "pg";
import { afterAll, expect, test } from "vitest";
import { pool } from "../lib/db";

// id из supabase/seed.sql: Марина — тренер Анны, Света — подопечная Игоря; тренировка 1 — «Ноги» Анны
const MARINA = "11111111-1111-1111-1111-111111111111";
const ANNA = "33333333-3333-3333-3333-333333333333";
const SVETA = "55555555-5555-5555-5555-555555555555";
const LEGS = 1;
const KNEE = "Последний подход тяжело, ноет колено";
const INSERT = "insert into comments (workout_id, author_id, body) values ($1, $2, $3)";

afterAll(() => pool.end());

// Запросы fn в одной транзакции с откатом; as(uid) — дальше от имени uid: роль authenticated и sub в request.jwt.claims
async function rolledBack<T>(fn: (db: PoolClient, as: (uid: string) => Promise<void>) => Promise<T>): Promise<T> {
  const db = await pool.connect();
  const as = async (uid: string) => {
    await db.query("set local role authenticated");
    await db.query("select set_config('request.jwt.claims', $1, true)", [JSON.stringify({ sub: uid, role: "authenticated" })]);
  };
  try {
    await db.query("begin");
    return await fn(db, as);
  } finally {
    await db.query("rollback");
    db.release();
  }
}

// Анна пишет комментарий под «Ногами», затем reader читает комментарии к этой тренировке
const commentsSeenBy = (reader: string) =>
  rolledBack(async (db, as) => {
    await as(ANNA);
    await db.query(INSERT, [LEGS, ANNA, KNEE]);
    await as(reader);
    const { rows } = await db.query<{ body: string }>("select body from comments where workout_id = $1", [LEGS]);
    return rows.map((row) => row.body);
  });

// uid пишет комментарий под «Ногами», автор — author
const write = (uid: string, author: string) =>
  rolledBack(async (db, as) => {
    await as(uid);
    await db.query(INSERT, [LEGS, author, "Привет от Светы"]);
  });

test("Света, подопечная Игоря, не видит комментарий Анны", async () => {
  expect(await commentsSeenBy(SVETA)).toEqual([]);
});

test("Анна видит свой комментарий", async () => {
  expect(await commentsSeenBy(ANNA)).toContain(KNEE);
});

test("Марина, тренер Анны, видит комментарий Анны", async () => {
  expect(await commentsSeenBy(MARINA)).toContain(KNEE);
});

test("Света не может написать под тренировкой Анны", async () => {
  await expect(write(SVETA, SVETA)).rejects.toThrow("row-level security");
});

test("Анна не может написать от имени Марины", async () => {
  await expect(write(ANNA, MARINA)).rejects.toThrow("row-level security");
});

import { expect, test } from "vitest";
import { coachNotices } from "./notify";

// Получатель — тренер Марина, её пояс — Москва. Время в тестах фиксированное: настоящие часы не участвуют
const MOSCOW = "Europe/Moscow";

// Тренировка из 5 упражнений по 3 подхода — 15 подходов, с 18:00 по Москве каждые 3 минуты
const START = Date.parse("2026-11-07T18:00:00+03:00");
const sets = Array.from({ length: 15 }, (_, i) => ({ workoutId: "1", savedAt: new Date(START + i * 3 * 60_000) }));

test("15 подходов одной тренировки — одно уведомление", () => {
  expect(coachNotices(sets, MOSCOW)).toEqual([{ workoutId: "1", sendAt: new Date("2026-11-07T18:00:00+03:00") }]);
});

// По Москве 23:40, а по UTC — 20:40: тихие часы считаются по поясу получателя, а не сервера
test("подход в 23:40 по Москве — уведомление в 8:00 утра", () => {
  const late = [{ workoutId: "1", savedAt: new Date("2026-11-07T23:40:00+03:00") }];
  expect(coachNotices(late, MOSCOW)).toEqual([{ workoutId: "1", sendAt: new Date("2026-11-08T08:00:00+03:00") }]);
});

// Уведомления тренеру о подходах подопечного — правила, тесты в lib/notify.test.ts:
// одно уведомление на тренировку, а не на каждый подход; ночью, с 22:00 до 8:00 по часовому поясу получателя, — в 8:00 утра.
// Своих часов у функций нет: время подхода приходит снаружи, поэтому тест проверяет их на фиксированных датах.

// Подход: в какой тренировке и когда сохранён
export type SavedSet = { workoutId: string; savedAt: Date };
// Уведомление тренеру: о какой тренировке и когда отправить
export type CoachNotice = { workoutId: string; sendAt: Date };

// Тихие часы по местному времени получателя: с 22:00 до 8:00
const QUIET_FROM = 22;
const QUIET_TO = 8;

// Местные дата и время в поясе timeZone (например, Europe/Moscow) — числами
function localTime(at: Date, timeZone: string) {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hourCycle: "h23",
    year: "numeric",
    month: "numeric",
    day: "numeric",
    hour: "numeric",
    minute: "numeric",
    second: "numeric",
  }).formatToParts(at);
  const part = (type: Intl.DateTimeFormatPartTypes) => Number(parts.find((p) => p.type === type)?.value);
  return { year: part("year"), month: part("month"), day: part("day"), hour: part("hour"), minute: part("minute"), second: part("second") };
}

// На сколько миллисекунд местное время пояса впереди UTC в момент at: у Москвы — на 3 часа
function offsetAt(at: Date, timeZone: string): number {
  const t = localTime(at, timeZone);
  return Date.UTC(t.year, t.month - 1, t.day, t.hour, t.minute, t.second) - Math.floor(at.getTime() / 1000) * 1000;
}

// Когда отправить уведомление о событии в момент at: днём — сразу, в тихие часы — в 8:00 по поясу получателя
// (после 22:00 — следующим утром, после полуночи — этим же)
export function sendTime(at: Date, timeZone: string): Date {
  const { year, month, day, hour } = localTime(at, timeZone);
  if (hour >= QUIET_TO && hour < QUIET_FROM) return at;
  // 8:00 по местным часам, записанные как время UTC; Date.UTC сам переносит 32-е число на следующий месяц
  const morning = Date.UTC(year, month - 1, hour >= QUIET_FROM ? day + 1 : day, QUIET_TO);
  // в UTC — минус сдвиг пояса, причём сдвиг на само утро: ночью пояс мог перейти на летнее время
  return new Date(morning - offsetAt(new Date(morning - offsetAt(at, timeZone)), timeZone));
}

// Уведомления тренеру о подходах: одно на тренировку — по её первому подходу, остальные подходы нового не дают
export function coachNotices(sets: SavedSet[], timeZone: string): CoachNotice[] {
  const first = new Map<string, Date>();
  for (const set of sets) {
    const seen = first.get(set.workoutId);
    if (!seen || set.savedAt.getTime() < seen.getTime()) first.set(set.workoutId, set.savedAt);
  }
  return [...first].map(([workoutId, savedAt]) => ({ workoutId, sendAt: sendTime(savedAt, timeZone) }));
}
